  1	import {
  2	  createCipheriv,
  3	  createDecipheriv,
  4	  createHmac,
  5	  pbkdf2Sync,
  6	  randomBytes,
  7	} from "node:crypto";
  8	import { Mnemonic, SigningKey, getAddress, keccak256, wordlists } from "ethers";
  9	import { ApiError, validationError } from "../errors.js";
 10	
 11	export const CHAIN_ID = "11155111";
 12	export const NETWORK = "sepolia";
 13	export const MAX_ADDRESS_INDEX = 2 ** 31 - 1;
 14	export const HARDENED_OFFSET = 2 ** 31;
 15	export const BIP44_ETHEREUM_PREFIX = [
 16	  44 + HARDENED_OFFSET,
 17	  60 + HARDENED_OFFSET,
 18	  HARDENED_OFFSET,
 19	  0,
 20	] as const;
 21	const SECP256K1_N = BigInt("0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141");
 22	
 23	export type HmacSha512 = (key: Uint8Array, data: Uint8Array) => Uint8Array;
 24	
 25	export type Bip44PathComponent = "purpose" | "coinType" | "account" | "change" | "addressIndex";
 26	
 27	export interface SkippedDerivation {
 28	  component: Bip44PathComponent;
 29	  index: number;
 30	}
 31	
 32	export interface DerivedAddress {
 33	  addressIndex: number;
 34	  address: string;
 35	  derivationPath: string;
 36	  publicKey: string;
 37	  skippedIndices?: number[];
 38	  skippedDerivations?: SkippedDerivation[];
 39	}
 40	
 41	export class InvalidDerivedKeyError extends Error {}
 42	
 43	function defaultHmacSha512(key: Uint8Array, data: Uint8Array): Uint8Array {
 44	  return createHmac("sha512", key).update(data).digest();
 45	}
 46	
 47	function parse256(value: Uint8Array): bigint {
 48	  return BigInt(`0x${Buffer.from(value).toString("hex")}`);
 49	}
 50	
 51	function serialize256(value: bigint): Buffer {
 52	  return Buffer.from(value.toString(16).padStart(64, "0"), "hex");
 53	}
 54	
 55	function serialize32(value: number): Buffer {
 56	  const result = Buffer.allocUnsafe(4);
 57	  result.writeUInt32BE(value, 0);
 58	  return result;
 59	}
 60	
 61	interface ExtendedPrivateKey {
 62	  privateKey: Buffer;
 63	  chainCode: Buffer;
 64	}
 65	
 66	function masterKey(seed: Uint8Array, hmac: HmacSha512): ExtendedPrivateKey {
 67	  const digest = Buffer.from(hmac(Buffer.from("Bitcoin seed", "utf8"), seed));
 68	  if (digest.length !== 64) throw new Error("Salida HMAC-SHA512 inválida");
 69	  const privateKey = digest.subarray(0, 32);
 70	  const keyNumber = parse256(privateKey);
 71	  if (keyNumber < 1n || keyNumber >= SECP256K1_N) {
 72	    throw new Error("Seed BIP-32 produjo una clave maestra inválida");
 73	  }
 74	  return { privateKey: Buffer.from(privateKey), chainCode: Buffer.from(digest.subarray(32)) };
 75	}
 76	
 77	function deriveChild(parent: ExtendedPrivateKey, index: number, hmac: HmacSha512): ExtendedPrivateKey {
 78	  const indexBytes = serialize32(index);
 79	  const data = index >= HARDENED_OFFSET
 80	    ? Buffer.concat([Buffer.from([0]), parent.privateKey, indexBytes])
 81	    : Buffer.concat([
 82	        Buffer.from(SigningKey.computePublicKey(parent.privateKey, true).slice(2), "hex"),
 83	        indexBytes,
 84	      ]);
 85	  const digest = Buffer.from(hmac(parent.chainCode, data));
 86	  if (digest.length !== 64) throw new Error("Salida HMAC-SHA512 inválida");
 87	  const left = parse256(digest.subarray(0, 32));
 88	  if (left >= SECP256K1_N) throw new InvalidDerivedKeyError("I_L está fuera de secp256k1");
 89	  const childNumber = (left + parse256(parent.privateKey)) % SECP256K1_N;
 90	  if (childNumber === 0n) throw new InvalidDerivedKeyError("La clave hija BIP-32 es cero");
 91	  return {
 92	    privateKey: serialize256(childNumber),
 93	    chainCode: Buffer.from(digest.subarray(32)),
 94	  };
 95	}
 96	
 97	interface DerivedChild {
 98	  extended: ExtendedPrivateKey;
 99	  index: number;
100	  skipped: SkippedDerivation[];
101	}
102	
103	/**
104	 * BIP-32 CKDpriv requires retrying the next child index when I_L or k_i is
105	 * invalid. The retry belongs to the component currently being derived: doing
106	 * it around the complete BIP-44 path would keep recomputing an invalid fixed
107	 * prefix for every address_index.
108	 */
109	function deriveNextValidChild(
110	  parent: ExtendedPrivateKey,
111	  requestedIndex: number,
112	  component: Bip44PathComponent,
113	  hmac: HmacSha512,
114	): DerivedChild {
115	  const upperBound = requestedIndex >= HARDENED_OFFSET ? 0xffff_ffff : MAX_ADDRESS_INDEX;
116	  const skipped: SkippedDerivation[] = [];
117	
118	  for (let index = requestedIndex; index <= upperBound; index += 1) {
119	    try {
120	      return { extended: deriveChild(parent, index, hmac), index, skipped };
121	    } catch (error) {
122	      if (!(error instanceof InvalidDerivedKeyError)) throw error;
123	      skipped.push({ component, index });
124	    }
125	  }
126	
127	  // Crossing 2^31 would silently change a normal child into a hardened one;
128	  // overflowing uint32 would likewise cease to be a valid BIP-32 child index.
129	  throw new ApiError("INTERNAL_ERROR");
130	}
131	
132	function formatPath(indices: readonly number[]): string {
133	  return `m/${indices.map((index) => (
134	    index >= HARDENED_OFFSET ? `${index - HARDENED_OFFSET}'` : String(index)
135	  )).join("/")}`;
136	}
137	
138	export function normalizeMnemonic(value: string): string {
139	  return value.normalize("NFKD").trim().replace(/\s+/g, " ");
140	}
141	
142	export function validateProjectMnemonic(value: string): string {
143	  const normalized = normalizeMnemonic(value);
144	  if (normalized.split(" ").length !== 24) {
145	    throw validationError([{ field: "mnemonic", message: "Debe contener exactamente 24 palabras" }]);
146	  }
147	  if (!Mnemonic.isValidMnemonic(normalized, wordlists.en)) {
148	    throw validationError([{ field: "mnemonic", message: "Wordlist o checksum BIP-39 inválido" }]);
149	  }
150	  return normalized;
151	}
152	
153	export function mnemonicToSeed(mnemonic: string, passphrase = ""): Buffer {
154	  const normalizedMnemonic = normalizeMnemonic(mnemonic);
155	  const normalizedPassphrase = passphrase.normalize("NFKD");
156	  return pbkdf2Sync(
157	    normalizedMnemonic,
158	    `mnemonic${normalizedPassphrase}`,
159	    2048,
160	    64,
161	    "sha512",
162	  );
163	}
164	
165	export function generateProjectSeed(passphrase = ""): { mnemonic: string; seed: Buffer } {
166	  const mnemonic = Mnemonic.fromEntropy(randomBytes(32), "", wordlists.en).phrase;
167	  return { mnemonic, seed: mnemonicToSeed(mnemonic, passphrase) };
168	}
169	
170	export function toChecksumAddress(rawAddress: string): string {
171	  const prefixed = rawAddress.startsWith("0x") ? rawAddress : `0x${rawAddress}`;
172	  return getAddress(prefixed.toLowerCase());
173	}
174	
175	export function encryptSeed(seed: Buffer, key: Buffer): Buffer {
176	  if (key.length !== 32) throw new Error("La clave AES debe tener 32 bytes");
177	  const nonce = randomBytes(12);
178	  const cipher = createCipheriv("aes-256-gcm", key, nonce, { authTagLength: 16 });
179	  const ciphertext = Buffer.concat([cipher.update(seed), cipher.final()]);
180	  return Buffer.concat([nonce, ciphertext, cipher.getAuthTag()]);
181	}
182	
183	export function decryptSeed(payload: Buffer, key: Buffer): Buffer {
184	  if (payload.length < 29 || key.length !== 32) throw new Error("Seed cifrado inválido");
185	  const nonce = payload.subarray(0, 12);
186	  const tag = payload.subarray(payload.length - 16);
187	  const ciphertext = payload.subarray(12, payload.length - 16);
188	  const decipher = createDecipheriv("aes-256-gcm", key, nonce, { authTagLength: 16 });
189	  decipher.setAuthTag(tag);
190	  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
191	}
192	
193	export function deriveAddress(
194	  seed: Uint8Array,
195	  addressIndex: number,
196	  hmac: HmacSha512 = defaultHmacSha512,
197	): DerivedAddress {
198	  if (!Number.isSafeInteger(addressIndex) || addressIndex < 0 || addressIndex > MAX_ADDRESS_INDEX) {
199	    throw validationError([
200	      { field: "address_index", message: `Debe estar entre 0 y ${MAX_ADDRESS_INDEX}` },
201	    ]);
202	  }
203	  let extended = masterKey(seed, hmac);
204	  const requestedIndices = [...BIP44_ETHEREUM_PREFIX, addressIndex];
205	  const components: readonly Bip44PathComponent[] = [
206	    "purpose",
207	    "coinType",
208	    "account",
209	    "change",
210	    "addressIndex",
211	  ];
212	  const effectiveIndices: number[] = [];
213	  const skippedDerivations: SkippedDerivation[] = [];
214	
215	  for (let position = 0; position < requestedIndices.length; position += 1) {
216	    const requestedIndex = requestedIndices[position]!;
217	    const component = components[position]!;
218	    const child = deriveNextValidChild(extended, requestedIndex, component, hmac);
219	    extended = child.extended;
220	    effectiveIndices.push(child.index);
221	    skippedDerivations.push(...child.skipped);
222	  }
223	
224	  const effectiveAddressIndex = effectiveIndices[effectiveIndices.length - 1]!;
225	  const skippedIndices = skippedDerivations
226	    .filter(({ component }) => component === "addressIndex")
227	    .map(({ index }) => index);
228	  const publicKey = SigningKey.computePublicKey(extended.privateKey, false);
229	  // Ethereum hashea X || Y (64 bytes), sin el byte SEC1 0x04.
230	  const publicKeyBytes = Buffer.from(publicKey.slice(4), "hex");
231	  const rawAddress = keccak256(publicKeyBytes).slice(-40);
232	  const result: DerivedAddress = {
233	    addressIndex: effectiveAddressIndex,
234	    address: toChecksumAddress(rawAddress),
235	    derivationPath: formatPath(effectiveIndices),
236	    publicKey,
237	  };
238	  if (skippedIndices.length > 0) result.skippedIndices = skippedIndices;
239	  if (skippedDerivations.length > 0) result.skippedDerivations = skippedDerivations;
240	  return result;
241	}
242	
243	export function deriveNextValidAddress(
244	  seed: Uint8Array,
245	  startIndex: number,
246	  hmac: HmacSha512 = defaultHmacSha512,
247	): DerivedAddress {
248	  return deriveAddress(seed, startIndex, hmac);
249	}

