     1	import { getAddress } from "ethers";
     2	
     3	export interface AppConfig {
     4	  host: string;
     5	  port: number;
     6	  databasePath: string;
     7	  sessionTtlSeconds: number;
     8	  walletEncryptionKey: Buffer;
     9	  usdcMockAddress: string;
    10	  sepoliaRpcUrl: string;
    11	  hdMnemonic?: string;
    12	  hdMnemonicPassphrase: string;
    13	  registerRateLimit?: RateLimitConfig;
    14	  loginRateLimit?: RateLimitConfig;
    15	  webOrigins?: string[];
    16	}
    17	
    18	export interface RateLimitConfig {
    19	  max: number;
    20	  windowSeconds: number;
    21	}
    22	
    23	function positiveInt(name: string, raw: string | undefined, fallback?: number): number {
    24	  if (raw === undefined && fallback !== undefined) return fallback;
    25	  if (raw === undefined || !/^[1-9][0-9]*$/.test(raw)) {
    26	    throw new Error(`INTERNAL_ERROR: ${name} debe ser un entero positivo`);
    27	  }
    28	  const value = Number(raw);
    29	  if (!Number.isSafeInteger(value)) {
    30	    throw new Error(`INTERNAL_ERROR: ${name} está fuera de rango`);
    31	  }
    32	  return value;
    33	}
    34	
    35	function encryptionKey(raw: string | undefined): Buffer {
    36	  if (!raw) throw new Error("INTERNAL_ERROR: falta WALLET_ENCRYPTION_KEY");
    37	  const value = raw.startsWith("base64:")
    38	    ? Buffer.from(raw.slice(7), "base64")
    39	    : Buffer.from(raw, "hex");
    40	  if (value.length !== 32) {
    41	    throw new Error("INTERNAL_ERROR: WALLET_ENCRYPTION_KEY debe contener exactamente 32 bytes");
    42	  }
    43	  return value;
    44	}
    45	
    46	function optionalRateLimit(
    47	  env: NodeJS.ProcessEnv,
    48	  maxName: string,
    49	  windowName: string,
    50	): RateLimitConfig | undefined {
    51	  const max = env[maxName];
    52	  const window = env[windowName];
    53	  if (max === undefined && window === undefined) return undefined;
    54	  if (max === undefined || window === undefined) {
    55	    throw new Error(`INTERNAL_ERROR: ${maxName} y ${windowName} deben configurarse juntos`);
    56	  }
    57	  return { max: positiveInt(maxName, max), windowSeconds: positiveInt(windowName, window) };
    58	}
    59	
    60	export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
    61	  const ttl = positiveInt("SESSION_TTL_SECONDS", env.SESSION_TTL_SECONDS, 3600);
    62	  if (ttl < 60 || ttl > 86_400) {
    63	    throw new Error("INTERNAL_ERROR: SESSION_TTL_SECONDS debe estar entre 60 y 86400");
    64	  }
    65	
