    33	
    34	  assignInsideTransaction(accountId: string): AddressRow {
    35	    const existing = this.store.findAddress(accountId);
    36	    if (existing) return existing;
    37	    const maxRow = this.store.db.prepare(
    38	      "SELECT MAX(address_index) AS max_index FROM deposit_addresses",
    39	    ).get() as { max_index: number | null };
    40	    const nextIndex = maxRow.max_index === null ? 0 : maxRow.max_index + 1;
    41	    const derived = this.hmac
    42	      ? deriveNextValidAddress(this.store.seed, nextIndex, this.hmac)
    43	      : deriveNextValidAddress(this.store.seed, nextIndex);
    44	    const createdAt = new Date().toISOString();
    45	    for (const skippedIndex of derived.skippedIndices ?? []) {
    46	      this.store.db.prepare(
    47	        `INSERT INTO skipped_address_indices (address_index, reason, occurred_at)
    48	         VALUES (?, 'INVALID_BIP32_CHILD', ?)`,
    49	      ).run(skippedIndex, createdAt);
    50	    }
    51	    const row = addressRecord(
    52	      accountId,
    53	      derived.addressIndex,
    54	      derived.address,
    55	      derived.derivationPath,
