 37	
 38	  constructor(readonly config: AppConfig) {
 39	    if (config.databasePath !== ":memory:") {
 40	      mkdirSync(dirname(resolve(config.databasePath)), { recursive: true });
 41	    }
 42	    this.db = new DatabaseSync(config.databasePath);
 43	    this.db.exec("PRAGMA foreign_keys = ON");
 44	    this.db.exec("PRAGMA journal_mode = WAL");
 45	    this.db.exec("PRAGMA synchronous = FULL");
 46	    this.db.exec("PRAGMA busy_timeout = 5000");
 47	    this.createSchema();
 48	    this.seed = this.loadOrProvisionSeed();
 49	    this.verifyWalletIntegrity();
 50	  }
 51	
 52	  close(): void {
 53	    this.db.close();
 54	  }
 55	
 56	  transaction<T>(operation: () => T): T {
 57	    this.db.exec("BEGIN IMMEDIATE");
 58	    try {
 59	      const result = operation();
 60	      this.db.exec("COMMIT");
 61	      return result;
 62	    } catch (error) {
 63	      this.db.exec("ROLLBACK");
 64	      throw error;
 65	    }
 66	  }
 67	
 68	  findAccountByEmail(email: string): AccountRow | undefined {
 69	    return this.db.prepare(
 70	      "SELECT account_id, email, password_hash, status, created_at FROM accounts WHERE email = ?",
 71	    ).get(email) as AccountRow | undefined;
 72	  }
 73	
 74	  findAccountById(accountId: string): AccountRow | undefined {
 75	    return this.db.prepare(
 76	      "SELECT account_id, email, password_hash, status, created_at FROM accounts WHERE account_id = ?",
 77	    ).get(accountId) as AccountRow | undefined;
 78	  }
 79	
 80	  findAddress(accountId: string): AddressRow | undefined {
 81	    return this.db.prepare(
 82	      `SELECT account_id, address_index, address, derivation_path, network, chain_id, created_at
 83	       FROM deposit_addresses WHERE account_id = ?`,
 84	    ).get(accountId) as AddressRow | undefined;
 85	  }
 86	
 87	  getAssignedAddresses(): AddressRow[] {
 88	    return this.db.prepare(
 89	      `SELECT account_id, address_index, address, derivation_path, network, chain_id, created_at
 90	       FROM deposit_addresses ORDER BY address_index ASC`,
 91	    ).all() as unknown as AddressRow[];
 92	  }
 93	
 94	  private createSchema(): void {
 95	    this.db.exec(`
 96	      CREATE TABLE IF NOT EXISTS accounts (
 97	        account_id TEXT PRIMARY KEY,
 98	        email TEXT NOT NULL UNIQUE,
 99	        password_hash TEXT NOT NULL,
100	        status TEXT NOT NULL CHECK (status = 'ACTIVE'),
101	        created_at TEXT NOT NULL
102	      ) STRICT;
103	
104	      CREATE TABLE IF NOT EXISTS sessions (
105	        token_hash TEXT PRIMARY KEY,
106	        account_id TEXT NOT NULL REFERENCES accounts(account_id),
107	        expires_at TEXT NOT NULL,
108	        created_at TEXT NOT NULL
109	      ) STRICT;
110	      CREATE INDEX IF NOT EXISTS sessions_account_id ON sessions(account_id);
111	
112	      CREATE TABLE IF NOT EXISTS wallet_metadata (
113	        key TEXT PRIMARY KEY,
114	        value BLOB NOT NULL
115	      ) STRICT;
116	
117	      CREATE TABLE IF NOT EXISTS deposit_addresses (
118	        account_id TEXT PRIMARY KEY REFERENCES accounts(account_id),
119	        address_index INTEGER NOT NULL UNIQUE CHECK (address_index >= 0 AND address_index < 2147483648),
120	        address TEXT NOT NULL UNIQUE,
121	        derivation_path TEXT NOT NULL,
122	        network TEXT NOT NULL CHECK (network = 'sepolia'),
123	        chain_id TEXT NOT NULL CHECK (chain_id = '11155111'),
124	        created_at TEXT NOT NULL
125	      ) STRICT;
126	
127	      CREATE TABLE IF NOT EXISTS domain_events (
128	        event_id TEXT PRIMARY KEY,
129	        event_type TEXT NOT NULL CHECK (event_type = 'DepositAddressAssigned'),
130	        account_id TEXT NOT NULL REFERENCES accounts(account_id),
131	        payload TEXT NOT NULL,
132	        occurred_at TEXT NOT NULL
133	      ) STRICT;
134	      CREATE INDEX IF NOT EXISTS domain_events_account_id ON domain_events(account_id);
135	
136	      CREATE TABLE IF NOT EXISTS skipped_address_indices (
137	        address_index INTEGER PRIMARY KEY CHECK (address_index >= 0 AND address_index < 2147483648),
138	        reason TEXT NOT NULL CHECK (reason = 'INVALID_BIP32_CHILD'),
139	        occurred_at TEXT NOT NULL
140	      ) STRICT;
141	
142	      CREATE TABLE IF NOT EXISTS auth_audit (
143	        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
144	        timestamp TEXT NOT NULL,
145	        email TEXT NOT NULL,
146	        result TEXT NOT NULL CHECK (result IN ('SUCCESS', 'FAILURE')),
147	        reason TEXT,
148	        origin TEXT
149	      ) STRICT;
150	    `);
151	  }
152	
153	  private loadOrProvisionSeed(): Buffer {
154	    const record = this.db.prepare("SELECT value FROM wallet_metadata WHERE key = 'encrypted_seed'").get() as
155	      | { value: Uint8Array }
156	      | undefined;
157	    if (record) {
158	      try {
159	        const seed = decryptSeed(Buffer.from(record.value), this.config.walletEncryptionKey);
160	        if (seed.length !== 64) throw new Error("Longitud de seed inválida");
161	        return seed;
162	      } catch {
163	        throw new Error("INTERNAL_ERROR: no se pudo descifrar o autenticar el seed custodial");
