185	      if (!persisted) throw new Error("No se pudo releer el seed cifrado");
186	      const verified = decryptSeed(Buffer.from(persisted.value), this.config.walletEncryptionKey);
187	      if (verified.length !== seed.length || !verified.equals(seed)) {
188	        throw new Error("No se pudo verificar el seed cifrado");
189	      }
190	    });
191	    return seed;
192	  }
193	
