195	    const row = this.db.prepare(
196	      "SELECT address_index, address FROM deposit_addresses ORDER BY address_index ASC LIMIT 1",
197	    ).get() as { address_index: number; address: string } | undefined;
198	    if (!row) return;
199	    try {
200	      const derived = deriveAddress(this.seed, row.address_index);
201	      if (derived.address !== row.address) throw new Error();
202	    } catch {
203	      throw new Error("INTERNAL_ERROR: falló el smoke test de integridad de la wallet HD");
204	    }
205	  }
