  1	import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from "fastify";
  2	import cors from "@fastify/cors";
  3	import type { AppConfig, RateLimitConfig } from "./config.js";
  4	import { Store, type AccountRow } from "./database.js";
  5	import { ApiError, validationError, type ValidationIssue } from "./errors.js";
  6	import { prepareDummyHash } from "./crypto/password.js";
  7	import { CHAIN_ID, NETWORK } from "./crypto/wallet.js";
  8	import { SlidingWindowRateLimiter } from "./rate-limit.js";
  9	import { AuthService, normalizeEmail, publicAccount } from "./services/auth-service.js";
 10	import { WalletService } from "./services/wallet-service.js";
 11	import {
 12	  attachPrivateWebSocket,
 13	  DEFAULT_PRIVATE_WEBSOCKET_TIMINGS,
 14	  type PrivateWebSocketTimings,
 15	} from "./private-websocket.js";
 16	
 17	declare module "fastify" {
 18	  interface FastifyRequest {
 19	    authenticatedAccount?: AccountRow;
 20	    loginAuditOutcome?: {
 21	      result: "SUCCESS" | "FAILURE";
 22	      reason?: string;
 23	    };
 24	    pendingPublicRateLimit?: {
 25	      kind: "register" | "login";
 26	      retryAfterSeconds: number;
 27	    };
 28	  }
 29	
 30	  interface FastifyInstance {
 31	    exchangeStore: Store;
 32	    authService: AuthService;
 33	    walletService: WalletService;
 34	  }
 35	}
 36	
 37	const EMAIL_PATTERN = /^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$/;
 38	const KNOWN_ROUTES: Readonly<Record<string, readonly string[]>> = {
 39	  "/api/v1/auth/register": ["POST"],
 40	  "/api/v1/auth/login": ["POST"],
 41	  "/api/v1/auth/logout": ["POST"],
 42	  "/api/v1/me": ["GET"],
 43	  "/api/v1/deposit-address": ["GET"],
 44	  "/health": ["GET"],
 45	};
 46	
 47	interface CredentialsBody {
 48	  email: string;
 49	  password: string;
 50	}
 51	
 52	function isRecord(value: unknown): value is Record<string, unknown> {
 53	  return value !== null && typeof value === "object" && !Array.isArray(value);
 54	}
 55	
 56	function validateCredentialsBody(value: unknown, exactFields: boolean): CredentialsBody {
 57	  const issues: ValidationIssue[] = [];
 58	  if (!isRecord(value)) {
 59	    throw validationError([{ field: "body", message: "Debe ser un objeto JSON" }]);
 60	  }
 61	  if (!("email" in value)) issues.push({ field: "email", message: "Campo requerido" });
 62	  else if (typeof value.email !== "string") issues.push({ field: "email", message: "Debe ser string" });
 63	  if (!("password" in value)) issues.push({ field: "password", message: "Campo requerido" });
 64	  else if (typeof value.password !== "string") {
 65	    issues.push({ field: "password", message: "Debe ser string" });
 66	  }
 67	  if (exactFields) {
 68	    for (const field of Object.keys(value)) {
 69	      if (field !== "email" && field !== "password") {
 70	        issues.push({ field, message: "Campo desconocido" });
 71	      }
 72	    }
 73	  }
 74	  if (issues.length > 0) throw validationError(issues);
 75	  return value as unknown as CredentialsBody;
 76	}
 77	
 78	function validateRegistration(body: CredentialsBody): CredentialsBody {
 79	  const email = normalizeEmail(body.email);
 80	  if (email.length > 254 || !EMAIL_PATTERN.test(email)) {
 81	    throw validationError([{ field: "email", message: "Formato de email inválido" }]);
 82	  }
 83	  const passwordLength = [...body.password].length;
 84	  if (passwordLength < 8 || passwordLength > 128) {
 85	    throw validationError([{ field: "password", message: "Debe tener entre 8 y 128 caracteres" }]);
 86	  }
 87	  return { email, password: body.password };
 88	}
 89	
 90	function bearerToken(request: FastifyRequest): string | undefined {
 91	  const authorization = request.headers.authorization;
 92	  if (typeof authorization !== "string") return undefined;
 93	  const match = /^Bearer ([^\s]+)$/.exec(authorization);
 94	  return match?.[1];
 95	}
 96	
 97	function sendRateLimit(reply: FastifyReply, retryAfterSeconds: number): never {
 98	  reply.header("Retry-After", String(retryAfterSeconds));
 99	  throw new ApiError("RATE_LIMITED", { retryAfterSeconds });
100	}
101	
102	function isLoginRequest(request: FastifyRequest): boolean {
103	  return request.method === "POST" && request.url.split("?", 1)[0] === "/api/v1/auth/login";
104	}
105	
106	function loginAttemptEmail(request: FastifyRequest): string {
107	  return isRecord(request.body) && typeof request.body.email === "string"
108	    ? request.body.email
109	    : "";
110	}
111	
112	export async function buildApp(
113	  config: AppConfig,
114	  privateWebSocketTimings: PrivateWebSocketTimings = DEFAULT_PRIVATE_WEBSOCKET_TIMINGS,
115	): Promise<FastifyInstance> {
116	  const app = Fastify({
117	    logger: false,
118	    exposeHeadRoutes: false,
119	    routerOptions: { ignoreTrailingSlash: false },
120	  });
121	  const store = new Store(config);
122	  const walletService = new WalletService(store);
123	  const authService = new AuthService(store, walletService);
124	  const publicLimiter = new SlidingWindowRateLimiter();
125	  const protectedLimiter = new SlidingWindowRateLimiter();
126	  await prepareDummyHash();
127	
128	  await app.register(cors, {
129	    origin: config.webOrigins ?? ["http://localhost:5173", "http://127.0.0.1:5173"],
130	    methods: ["GET", "POST", "DELETE", "OPTIONS"],
131	    allowedHeaders: ["Content-Type", "Authorization"],
132	    credentials: false,
133	  });
134	
135	  app.decorate("exchangeStore", store);
136	  app.decorate("walletService", walletService);
137	  app.decorate("authService", authService);
138	
139	  const closePrivateWebSocket = attachPrivateWebSocket(
140	    app.server,
141	    authService,
142	    privateWebSocketTimings,
143	  );
144	
145	  app.addHook("onClose", async () => {
146	    closePrivateWebSocket();
147	    store.close();
148	  });
149	
150	  app.setErrorHandler((error, request, reply) => {
151	    if (request.pendingPublicRateLimit) {
152	      const retryAfterSeconds = request.pendingPublicRateLimit.retryAfterSeconds;
153	      const apiError = new ApiError("RATE_LIMITED", { retryAfterSeconds });
154	      if (isLoginRequest(request)) {
155	        request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
156	      }
157	      reply.header("Retry-After", String(retryAfterSeconds));
158	      reply.status(apiError.status).send(apiError.toBody());
159	      return;
160	    }
161	    if (error instanceof ApiError) {
162	      if (isLoginRequest(request)) {
163	        request.loginAuditOutcome = { result: "FAILURE", reason: error.code };
164	      }
165	      reply.status(error.status).send(error.toBody());
166	      return;
167	    }
168	    const fastifyError = error as Error & { code?: string; statusCode?: number };
169	    if (
170	      fastifyError.code === "FST_ERR_CTP_INVALID_MEDIA_TYPE" ||
171	      fastifyError.code === "FST_ERR_CTP_EMPTY_JSON_BODY" ||
172	      fastifyError.code === "FST_ERR_CTP_BODY_TOO_LARGE" ||
173	      fastifyError.statusCode === 400
174	    ) {
175	      const apiError = validationError([{ field: "body", message: "JSON inválido o Content-Type no soportado" }]);
176	      if (isLoginRequest(request)) {
177	        request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
178	      }
179	      reply.status(apiError.status).send(apiError.toBody());
180	      return;
181	    }
182	    const apiError = new ApiError("INTERNAL_ERROR");
183	    if (isLoginRequest(request)) {
184	      request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
185	    }
186	    reply.status(apiError.status).send(apiError.toBody());
187	  });
188	
189	  app.addHook("onResponse", async (request) => {
190	    if (!isLoginRequest(request)) return;
191	    const outcome = request.loginAuditOutcome ?? { result: "FAILURE", reason: "INTERNAL_ERROR" } as const;
192	    authService.auditLoginAttempt(
193	      loginAttemptEmail(request),
194	      outcome.result,
195	      outcome.reason,
196	      request.ip,
197	    );
198	  });
199	
200	  app.setNotFoundHandler((request, reply) => {
201	    const path = request.url.split("?", 1)[0] ?? request.url;
202	    const allowed = KNOWN_ROUTES[path];
203	    const error = allowed && !allowed.includes(request.method)
204	      ? new ApiError("METHOD_NOT_ALLOWED", { method: request.method, allowed })
205	      : new ApiError("NOT_FOUND", { resource: "route", id: path });
206	    reply.status(error.status).send(error.toBody());
207	  });
208	
209	  app.get("/health", async () => ({ status: "ok" }));
210	
211	  const publicRateLimitCheck = (kind: "register" | "login", rateConfig: RateLimitConfig | undefined) =>
212	    async (request: FastifyRequest): Promise<void> => {
213	      if (!rateConfig) return;
214	      const result = publicLimiter.check(`${kind}:${request.ip}`, rateConfig);
215	      if (result.limited) {
216	        request.pendingPublicRateLimit = { kind, retryAfterSeconds: result.retryAfterSeconds };
217	      }
218	    };
219	
220	  const enforcePublicRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
221	    const pending = request.pendingPublicRateLimit;
222	    if (!pending) return;
223	    sendRateLimit(reply, pending.retryAfterSeconds);
224	  };
225	
226	  app.post(
227	    "/api/v1/auth/register",
228	    {
229	      onRequest: publicRateLimitCheck("register", config.registerRateLimit),
230	      preValidation: enforcePublicRateLimit,
231	    },
232	    async (request, reply) => {
233	      const schemaValid = validateCredentialsBody(request.body, true);
234	      const body = validateRegistration(schemaValid);
235	      if (store.findAccountByEmail(body.email)) {
236	        throw new ApiError("EMAIL_ALREADY_EXISTS", { email: body.email });
237	      }
238	      const account = await authService.register(body.email, body.password);
239	      reply.status(201).send(account);
240	    },
241	  );
242	
243	  app.post(
244	    "/api/v1/auth/login",
245	    {
246	      onRequest: publicRateLimitCheck("login", config.loginRateLimit),
247	      preValidation: enforcePublicRateLimit,
248	    },
249	    async (request, reply) => {
250	      const body = validateCredentialsBody(request.body, false);
251	      const result = await authService.login(body.email, body.password);
252	      request.loginAuditOutcome = { result: "SUCCESS" };
253	      reply.status(200).send(result);
254	    },
255	  );
256	
257	  const authenticate = async (request: FastifyRequest): Promise<void> => {
258	    const token = bearerToken(request);
259	    const account = token ? authService.authenticate(token) : undefined;
260	    if (!account) throw new ApiError("UNAUTHENTICATED");
261	    request.authenticatedAccount = account;
262	  };
263	
264	  const protectedRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
265	    const account = request.authenticatedAccount;
266	    if (!account) throw new ApiError("UNAUTHENTICATED");
267	    const result = protectedLimiter.check(
268	      `${account.account_id}:${request.routeOptions.url}`,
269	      { max: 60, windowSeconds: 60 },
270	    );
271	    if (result.limited) sendRateLimit(reply, result.retryAfterSeconds);
272	  };
273	
274	  app.post(
275	    "/api/v1/auth/logout",
276	    { onRequest: [authenticate, protectedRateLimit] },
277	    async (request, reply) => {
278	      const token = bearerToken(request);
279	      if (!token || !authService.logout(token)) throw new ApiError("UNAUTHENTICATED");
280	      reply.status(204).send();
281	    },
282	  );
283	
284	  app.get(
285	    "/api/v1/me",
286	    { onRequest: [authenticate, protectedRateLimit] },
287	    async (request, reply) => {
288	      const account = request.authenticatedAccount;
289	      if (!account) throw new ApiError("UNAUTHENTICATED");
290	      reply.status(200).send(publicAccount(account));
291	    },
292	  );
293	
294	  app.get(
295	    "/api/v1/deposit-address",
296	    { onRequest: [authenticate, protectedRateLimit] },
297	    async (request, reply) => {
298	      const query = isRecord(request.query) ? request.query : {};
299	      const asset = query.asset;
300	      if (typeof asset !== "string" || (asset !== "ETH" && asset !== "USDC")) {
301	        throw validationError([{ field: "asset", message: "Debe ser ETH o USDC" }]);
302	      }
303	
304	      const chainId = query.chainId;
305	      const network = query.network;
306	      if (chainId !== undefined && String(chainId) !== CHAIN_ID) {
307	        throw new ApiError("CHAIN_ID_MISMATCH", { expected: CHAIN_ID, got: String(chainId) });
308	      }
309	      if (network !== undefined && String(network).toLowerCase() !== NETWORK) {
310	        throw new ApiError("CHAIN_ID_MISMATCH", { expected: CHAIN_ID, got: String(network) });
311	      }
312	
313	      const account = request.authenticatedAccount;
314	      if (!account) throw new ApiError("UNAUTHENTICATED");
315	      const assigned = walletService.getOrAssign(account.account_id);
316	      const response: Record<string, string> = {
317	        asset,
318	        address: assigned.address,
319	        network: NETWORK,
320	        chainId: CHAIN_ID,
321	      };
322	      if (asset === "USDC") response.tokenAddress = config.usdcMockAddress;
323	      reply.status(200).send(response);
324	    },
325	  );
326	
327	  return app;
