     1	import { createHash, randomBytes, randomUUID } from "node:crypto";
     2	import type { Store, AccountRow } from "../database.js";
     3	import { ApiError } from "../errors.js";
     4	import { hashPassword, verifyAgainstDummy, verifyPassword } from "../crypto/password.js";
     5	import type { WalletService } from "./wallet-service.js";
     6	
     7	export interface PublicAccount {
     8	  accountId: string;
     9	  email: string;
    10	  status: "ACTIVE";
    11	  createdAt: string;
    12	}
    13	
    14	export interface LoginResult {
    15	  token: string;
    16	  expiresAt: string;
    17	}
    18	
    19	export interface AuthenticatedSession {
    20	  account: AccountRow;
    21	  expiresAt: string;
    22	}
    23	
    24	export function publicAccount(row: AccountRow): PublicAccount {
    25	  return {
    26	    accountId: row.account_id,
    27	    email: row.email,
    28	    status: row.status,
    29	    createdAt: row.created_at,
    30	  };
    31	}
    32	
    33	function tokenHash(token: string): string {
    34	  return createHash("sha256").update(token, "utf8").digest("hex");
    35	}
    36	
    37	export function normalizeEmail(email: string): string {
    38	  return email.trim().toLowerCase();
    39	}
    40	
    41	export class AuthService {
    42	  constructor(
    43	    private readonly store: Store,
    44	    private readonly walletService: WalletService,
    45	  ) {}
    46	
    47	  async register(email: string, password: string): Promise<PublicAccount> {
    48	    const normalizedEmail = normalizeEmail(email);
    49	    const passwordHash = await hashPassword(password);
    50	    const account: AccountRow = {
    51	      account_id: randomUUID(),
    52	      email: normalizedEmail,
    53	      password_hash: passwordHash,
    54	      status: "ACTIVE",
    55	      created_at: new Date().toISOString(),
    56	    };
    57	    try {
    58	      this.store.transaction(() => {
    59	        this.store.db.prepare(
    60	          `INSERT INTO accounts (account_id, email, password_hash, status, created_at)
    61	           VALUES (?, ?, ?, ?, ?)`,
    62	        ).run(
    63	          account.account_id,
    64	          account.email,
    65	          account.password_hash,
    66	          account.status,
    67	          account.created_at,
    68	        );
    69	        this.walletService.assignInsideTransaction(account.account_id);
    70	      });
    71	    } catch (error) {
    72	      if (error instanceof Error && /UNIQUE constraint failed: accounts\.email/.test(error.message)) {
    73	        throw new ApiError("EMAIL_ALREADY_EXISTS", { email: normalizedEmail });
    74	      }
    75	      throw error;
    76	    }
    77	    return publicAccount(account);
    78	  }
    79	
    80	  async login(email: string, password: string): Promise<LoginResult> {
    81	    const normalizedEmail = normalizeEmail(email);
    82	    const account = this.store.findAccountByEmail(normalizedEmail);
    83	    let valid = false;
    84	    if (account) {
    85	      valid = await verifyPassword(password, account.password_hash);
    86	    } else {
    87	      await verifyAgainstDummy(password);
    88	    }
    89	
    90	    if (!account || !valid) {
    91	      throw new ApiError("INVALID_CREDENTIALS");
    92	    }
    93	
    94	    const token = randomBytes(32).toString("base64url");
    95	    const now = new Date();
    96	    const expiresAt = new Date(now.getTime() + this.store.config.sessionTtlSeconds * 1000).toISOString();
    97	    this.store.db.prepare(
    98	      "INSERT INTO sessions (token_hash, account_id, expires_at, created_at) VALUES (?, ?, ?, ?)",
    99	    ).run(tokenHash(token), account.account_id, expiresAt, now.toISOString());
   100	    return { token, expiresAt };
   101	  }
   102	
   103	  authenticateSession(token: string): AuthenticatedSession | undefined {
   104	    const session = this.store.db.prepare(
   105	      `SELECT a.account_id, a.email, a.password_hash, a.status, a.created_at, s.expires_at
   106	       FROM sessions s JOIN accounts a ON a.account_id = s.account_id
   107	       WHERE s.token_hash = ?`,
   108	    ).get(tokenHash(token)) as (AccountRow & { expires_at: string }) | undefined;
   109	    if (!session) return undefined;
   110	    const expiration = Date.parse(session.expires_at);
   111	    if (!Number.isFinite(expiration) || expiration <= Date.now()) return undefined;
   112	    return { account: session, expiresAt: session.expires_at };
   113	  }
   114	
   115	  authenticate(token: string): AccountRow | undefined {
   116	    return this.authenticateSession(token)?.account;
   117	  }
   118	
   119	  /**
   120	   * The conditional DELETE is both the authentication check and the revocation
   121	   * CAS. SQLite serializes this statement, so concurrent logouts cannot both
   122	   * observe success. Removing an opaque session is a durable denylist-equivalent:
   123	   * it cannot become valid again after a restart.
   124	   */
   125	  logout(token: string): boolean {
   126	    const result = this.store.db.prepare(
   127	      "DELETE FROM sessions WHERE token_hash = ? AND expires_at > ?",
   128	    ).run(tokenHash(token), new Date().toISOString());
   129	    return result.changes === 1;
   130	  }
   131	
   132	  auditLoginAttempt(
   133	    email: string,
   134	    result: "SUCCESS" | "FAILURE",
   135	    reason?: string,
   136	    origin?: string,
   137	  ): void {
   138	    const normalizedEmail = normalizeEmail(email);
   139	    this.store.db.prepare(
   140	      `INSERT INTO auth_audit (timestamp, email, result, reason, origin)
   141	       VALUES (?, ?, ?, ?, ?)`,
   142	    ).run(new Date().toISOString(), normalizedEmail, result, reason ?? null, origin ?? null);
   143	  }
   144	}
