     6	  UNAUTHORIZED: 403,
     7	  VALIDATION_ERROR: 422,
     8	  CHAIN_ID_MISMATCH: 422,
     9	  NOT_FOUND: 404,
    10	  ACCOUNT_NOT_FOUND: 404,
    11	  METHOD_NOT_ALLOWED: 405,
    12	  EMAIL_ALREADY_EXISTS: 409,
    13	  RATE_LIMITED: 429,
    14	  INTERNAL_ERROR: 500,
    15	};
    16	
    17	const MESSAGES: Readonly<Record<string, string>> = {
    18	  UNAUTHENTICATED: "Se requiere una credencial válida.",
    19	  INVALID_CREDENTIALS: "Las credenciales son incorrectas.",
    20	  UNAUTHORIZED: "La credencial no autoriza esta operación.",
    21	  VALIDATION_ERROR: "La solicitud no cumple el esquema esperado.",
    22	  CHAIN_ID_MISMATCH: "La red solicitada no es Sepolia.",
    23	  NOT_FOUND: "El recurso solicitado no existe.",
    24	  ACCOUNT_NOT_FOUND: "La cuenta solicitada no existe.",
    25	  METHOD_NOT_ALLOWED: "El método HTTP no está permitido para esta ruta.",
    26	  EMAIL_ALREADY_EXISTS: "Ya existe una cuenta para el email indicado.",
    27	  RATE_LIMITED: "Se superó el límite de solicitudes permitido.",
    28	  INTERNAL_ERROR: "Ocurrió un error interno.",
    29	};
    30	
    31	export class ApiError extends Error {
    32	  readonly code: string;
    33	  readonly status: number;
    34	  readonly details?: ErrorDetails;
    35	
    36	  constructor(code: string, details?: ErrorDetails, message?: string, status?: number) {
    37	    super(message ?? MESSAGES[code] ?? MESSAGES.INTERNAL_ERROR);
    38	    this.name = "ApiError";
    39	    this.code = code;
    40	    this.status = status ?? HTTP_STATUS[code] ?? 500;
    41	    if (details !== undefined) this.details = details;
    42	  }
    43	
    44	  toBody(): { error: { code: string; message: string; details?: ErrorDetails } } {
    45	    const error: { code: string; message: string; details?: ErrorDetails } = {
    46	      code: this.code,
    47	      message: this.message,
    48	    };
    49	    if (this.details !== undefined) error.details = this.details;
    50	    return { error };
    51	  }
    52	}
    53	
    54	export interface ValidationIssue {
    55	  field: string;
    56	  message: string;
    57	}
    58	
    59	export function validationError(issues: ValidationIssue[]): ApiError {
    60	  return new ApiError("VALIDATION_ERROR", { issues });
