    47	  async register(email: string, password: string): Promise<PublicAccount> {
    48	    const normalizedEmail = normalizeEmail(email);
    49	    const passwordHash = await hashPassword(password);
    50	    const account: AccountRow = {
    51	      account_id: randomUUID(),
    52	      email: normalizedEmail,
    53	      password_hash: passwordHash,
    54	      status: "ACTIVE",
    55	      created_at: new Date().toISOString(),
    56	    };
    57	    try {
    58	      this.store.transaction(() => {
    59	        this.store.db.prepare(
    60	          `INSERT INTO accounts (account_id, email, password_hash, status, created_at)
    61	           VALUES (?, ?, ?, ?, ?)`,
    62	        ).run(
    63	          account.account_id,
    64	          account.email,
    65	          account.password_hash,
    66	          account.status,
    67	          account.created_at,
    68	        );
