  1	import { createHmac, randomBytes } from "node:crypto";
  2	import { describe, expect, it } from "vitest";
  3	import {
  4	  decryptSeed,
  5	  deriveAddress,
  6	  deriveNextValidAddress,
  7	  encryptSeed,
  8	  generateProjectSeed,
  9	  mnemonicToSeed,
 10	  toChecksumAddress,
 11	  validateProjectMnemonic,
 12	  BIP44_ETHEREUM_PREFIX,
 13	} from "../src/crypto/wallet.js";
 14	
 15	const BIP39_MNEMONIC = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
 16	const HARDHAT_MNEMONIC = "test test test test test test test test test test test junk";
 17	const SECP256K1_N = BigInt("0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141");
 18	
 19	function invalidLeftAtChildIndex(targetIndex: number) {
 20	  return (key: Uint8Array, data: Uint8Array) => {
 21	    const input = Buffer.from(data);
 22	    if (input.length === 37 && input.readUInt32BE(33) === targetIndex) {
 23	      return Buffer.concat([
 24	        Buffer.from(SECP256K1_N.toString(16).padStart(64, "0"), "hex"),
 25	        Buffer.alloc(32),
 26	      ]);
 27	    }
 28	    return createHmac("sha512", key).update(input).digest();
 29	  };
 30	}
 31	
 32	describe("wallet HD", () => {
 33	  it("cumple el vector canónico BIP-39", () => {
 34	    expect(mnemonicToSeed(BIP39_MNEMONIC, "TREZOR").toString("hex")).toBe(
 35	      "c55257c360c07c72029aebc1b53c05ed0362ada38ead3e3e9efa3708e53495531f09a6987599d18264c1e1c92f2cf141630c7a3c4ab7c81b2f001698e7463b04",
 36	    );
 37	  });
 38	
 39	  it("genera mnemonics BIP-39 válidos de 24 palabras y distintos", () => {
 40	    const first = generateProjectSeed();
 41	    const second = generateProjectSeed();
 42	    expect(first.mnemonic.split(" ")).toHaveLength(24);
 43	    expect(validateProjectMnemonic(first.mnemonic)).toBe(first.mnemonic);
 44	    expect(first.seed).toHaveLength(64);
 45	    expect(second.mnemonic).not.toBe(first.mnemonic);
 46	    expect(second.seed.equals(first.seed)).toBe(false);
 47	  });
 48	
 49	  it("rechaza mnemonics válidos de longitud no permitida para provisioning", () => {
 50	    expect(() => validateProjectMnemonic(BIP39_MNEMONIC)).toThrowError(
 51	      expect.objectContaining({ details: { issues: [{ field: "mnemonic", message: expect.stringMatching(/24 palabras/) }] } }),
 52	    );
 53	    const invalid24 = `${"abandon ".repeat(23)}notaword`;
 54	    expect(() => validateProjectMnemonic(invalid24)).toThrow();
 55	  });
 56	
 57	  it("cifra el seed con AES-256-GCM y detecta key/tag incorrectos", () => {
 58	    const seed = randomBytes(64);
 59	    const key = randomBytes(32);
 60	    const first = encryptSeed(seed, key);
 61	    const second = encryptSeed(seed, key);
 62	    expect(first).not.toEqual(second);
 63	    expect(decryptSeed(first, key)).toEqual(seed);
 64	    expect(() => decryptSeed(first, randomBytes(32))).toThrow();
 65	    first[first.length - 1]! ^= 1;
 66	    expect(() => decryptSeed(first, key)).toThrow();
 67	  });
 68	
 69	  it("cumple los vectores BIP-44/Ethereum de Hardhat", () => {
 70	    const seed = mnemonicToSeed(HARDHAT_MNEMONIC);
 71	    const expected = [
 72	      "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266",
 73	      "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
 74	      "0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC",
 75	      "0x90F79bf6EB2c4f870365E785982E1f101E93b906",
 76	    ];
 77	    expected.forEach((address, index) => {
 78	      const derived = deriveAddress(seed, index);
 79	      expect(derived.address).toBe(address);
 80	      expect(derived.derivationPath).toBe(`m/44'/60'/0'/0/${index}`);
 81	      expect(derived.publicKey).toMatch(/^0x04[0-9a-fA-F]{128}$/);
 82	    });
 83	  });
 84	
 85	  it("cumple los vectores de checksum EIP-55", () => {
 86	    const vectors = [
 87	      ["5aaeb6053f3e94c9b9a09f33669435e7ef1beaed", "0x5aAeb6053F3E94C9b9A09f33669435E7Ef1BeAed"],
 88	      ["fb6916095ca1df60bb79ce92ce3ea74c37c5d359", "0xfB6916095ca1df60bB79Ce92cE3Ea74c37c5d359"],
 89	      ["dbf03b407c01e7cd3cbea99509d93f8dddc8c6fb", "0xdbF03B407c01E7cD3CBea99509d93f8DDDC8C6FB"],
 90	      ["d1220a0cf47c7b9be7a2e6ba89f429762e7b9adb", "0xD1220A0cf47c7B9Be7A2E6BA89F429762e7b9aDb"],
 91	    ];
 92	    for (const [raw, checksummed] of vectors) expect(toChecksumAddress(raw!)).toBe(checksummed);
 93	  });
 94	
 95	  it("valida el rango no-hardened", () => {
 96	    const seed = mnemonicToSeed(HARDHAT_MNEMONIC);
 97	    expect(() => deriveAddress(seed, 2 ** 31)).toThrowError(/VALIDATION_ERROR|solicitud/i);
 98	    expect(deriveAddress(seed, 2 ** 31 - 1).address).toMatch(/^0x[0-9a-fA-F]{40}$/);
 99	    expect(BIP44_ETHEREUM_PREFIX).toEqual([2147483692, 2147483708, 2147483648, 0]);
100	  });
