102	  it.each([
103	    ["purpose", 2147483692, "m/45'/60'/0'/0/7"],
104	    ["coinType", 2147483708, "m/44'/61'/0'/0/7"],
105	    ["account", 2147483648, "m/44'/60'/1'/0/7"],
106	    ["change", 0, "m/44'/60'/0'/1/7"],
107	    ["addressIndex", 7, "m/44'/60'/0'/0/8"],
108	  ] as const)(
109	    "salta un I_L inválido en el componente %s sin recalcular el path completo",
110	    (component, skippedIndex, expectedPath) => {
111	      const seed = mnemonicToSeed(HARDHAT_MNEMONIC);
112	      const first = deriveNextValidAddress(seed, 7, invalidLeftAtChildIndex(skippedIndex));
113	      const second = deriveNextValidAddress(seed, 7, invalidLeftAtChildIndex(skippedIndex));
114	
115	      expect(first).toEqual(second);
116	      expect(first.derivationPath).toBe(expectedPath);
117	      expect(first.skippedDerivations).toEqual([{ component, index: skippedIndex }]);
118	      if (component === "addressIndex") {
119	        expect(first.addressIndex).toBe(8);
120	        expect(first.skippedIndices).toEqual([7]);
121	        expect(first.address).toBe(deriveAddress(seed, 8).address);
122	      } else {
123	        expect(first.addressIndex).toBe(7);
124	        expect(first.skippedIndices).toBeUndefined();
125	      }
126	    },
127	  );
128	
129	  it("salta también una clave hija cero", () => {
130	    const seed = mnemonicToSeed(HARDHAT_MNEMONIC);
131	    let injected = false;
132	    const zeroChildHmac = (key: Uint8Array, data: Uint8Array) => {
133	      const input = Buffer.from(data);
134	      if (!injected && input.length === 37 && input.readUInt32BE(33) === BIP44_ETHEREUM_PREFIX[0]) {
135	        injected = true;
136	        const parentKey = BigInt(`0x${input.subarray(1, 33).toString("hex")}`);
137	        const left = SECP256K1_N - parentKey;
138	        return Buffer.concat([
139	          Buffer.from(left.toString(16).padStart(64, "0"), "hex"),
140	          Buffer.alloc(32),
141	        ]);
142	      }
143	      return createHmac("sha512", key).update(input).digest();
144	    };
145	
146	    const result = deriveAddress(seed, 7, zeroChildHmac);
147	    expect(result.derivationPath).toBe("m/45'/60'/0'/0/7");
148	    expect(result.skippedDerivations).toEqual([{ component: "purpose", index: 2147483692 }]);
149	  });
150	});

