// Verificación INDEPENDIENTE del SUT de las constantes de mnemonic de la rúbrica.
// Algoritmo: corpus/documentos/bip-0039.mediawiki §"Generating the mnemonic".
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";

const WORDLIST = readFileSync(process.argv[2], "utf8").split("\n").map(w => w.trim()).filter(Boolean);
console.log("wordlist palabras =", WORDLIST.length);

function mnemonicFromEntropy(entropy) {
  const cs = (entropy.length * 8) / 32;              // CS = ENT/32
  const hash = createHash("sha256").update(entropy).digest();
  let bits = [...entropy].map(b => b.toString(2).padStart(8, "0")).join("");
  bits += [...hash].map(b => b.toString(2).padStart(8, "0")).join("").slice(0, cs);
  const words = [];
  for (let i = 0; i < bits.length; i += 11) words.push(WORDLIST[parseInt(bits.slice(i, i + 11), 2)]);
  return words.join(" ");
}

