import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { generateProjectSeed } from "../src/crypto/wallet.js";

const WORDLIST = readFileSync(process.argv[2]!, "utf8").split("\n").map(w => w.trim()).filter(Boolean);
// Validador BIP-39 independiente del SUT (corpus §"Generating the mnemonic").
function checksumValido(frase: string): boolean {
  const words = frase.split(" ");
  const bits = words.map(w => WORDLIST.indexOf(w).toString(2).padStart(11, "0")).join("");
  const cs = bits.length / 33, ent = bits.length - cs;
  const entropy = Buffer.from((bits.slice(0, ent).match(/.{8}/g) ?? []).map(b => parseInt(b, 2)));
  const esperado = [...createHash("sha256").update(entropy).digest()]
    .map(b => b.toString(2).padStart(8, "0")).join("").slice(0, cs);
  return bits.slice(ent) === esperado && entropy.length * 8 === 256;
}

for (const n of [1, 2]) {
  const { mnemonic, seed } = generateProjectSeed();
  console.log(`gen${n}: palabras=${mnemonic.split(" ").length} seedBytes=${seed.length} checksum256bitsValido=${checksumValido(mnemonic)} todasEnWordlist=${mnemonic.split(" ").every(w => WORDLIST.includes(w))}`);
}
EOF
